// Generated by :web:buildSite from web/src/main/templates/sw.js - don't edit the copy in build/site.
// Precaches the whole site on install so it works offline after one visit
// (design.md decision 9). The cache version is a hash of the site's contents,
// so every deploy that changes anything gets a fresh cache.
const CACHE_PREFIX = "bitcoin-bites-";
const CACHE = CACHE_PREFIX + "__CACHE_VERSION__";
const PRECACHE = [
  __PRECACHE_URLS__
];

const scopeUrl = (path) => new URL(path, self.registration.scope).href;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE)
      // cache: "reload" skips the browser's HTTP cache - GitHub Pages sends
      // max-age=600, so a plain fetch here could fill the new cache with the
      // previous deploy's files.
      .then((cache) => cache.addAll(PRECACHE.map((path) => new Request(scopeUrl(path), { cache: "reload" }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(
        keys.filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE).map((key) => caches.delete(key)),
      ))
      .then(() => self.clients.claim()),
  );
});

// Everything is network-first with the cache as the offline fallback. Pages,
// facts.json, JS and CSS change together on each deploy, so serving any of
// them from cache while online could pair new HTML with old scripts.
async function networkFirst(request) {
  const cache = await caches.open(CACHE);
  try {
    const response = await fetch(request);
    if (response.ok) cache.put(request, response.clone());
    return response;
  } catch (error) {
    const cached = await cache.match(request);
    if (cached) return cached;
    if (request.mode === "navigate") {
      const notFound = await cache.match(scopeUrl("404.html"));
      if (notFound) return notFound;
    }
    throw error;
  }
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET" || !request.url.startsWith(self.registration.scope)) return;
  event.respondWith(networkFirst(request));
});
